import { useState, KeyboardEvent } from 'react';
import { JxInputField, JxChip } from '@jinx-ui/react';

interface ArticleTagsInputProps {
  onChange?: (tags: string[]) => void;
  initialTags?: string[];
}

export default function ArticleTagsInput({ onChange, initialTags = [] }: ArticleTagsInputProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commitTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const addTag = () => {
    const trimmed = draft.trim();
    if (!trimmed || tags.includes(trimmed)) {
      setDraft('');
      return;
    }
    commitTags([...tags, trimmed]);
    setDraft('');
  };

  const removeTag = (tag: string) => {
    commitTags(tags.filter((t) => t !== tag));
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      addTag();
    } else if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      commitTags(tags.slice(0, -1));
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <JxInputField
        label="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        helperText="Enter добавляет тег, Backspace удаляет последний"
        value={draft}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-r-sm)' }}>
          {tags.map((tag) => (
            <JxChip key={tag} removable onRemove={() => removeTag(tag)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

